function footer(){return `<footer><div><a class="brand" href="#/">ELITE<span>/</span>ONE</a><p>Private performance coaching.<br>Berlin · Worldwide</p></div><div class="footer-links"><a href="#/nutrition">Nutrition</a><a href="#/workouts">Exercise library</a><a href="#/client">Client Area</a><a href="#/trainer">Trainer Panel</a></div><div><p class="eyebrow">Запуск 2025 — демо-версия</p><p>© Elite One. Все данные в кабинете — демонстрационные.</p></div></footer>`}
