function about(){const values=[['01','Сначала контекст','Работа, сон, прошлый опыт и здоровье имеют значение прежде, чем появится первая тренировка.','context'],['02','Затем система','Простая структура, которую можно продолжать даже в насыщенные недели.','system'],['03','Потом интенсивность','Усложняем только то, что уже стало устойчивым.','intensity']];layout(`<section class="page-head wrap"><p class="eyebrow">About coach</p><h1>Тренер — это<br><em>ваша система</em> опоры.</h1><p>Daniel Ross работает на стыке силового тренинга, поведенческого дизайна и точной обратной связи. Это вымышленный профиль для демонстрации интерфейса.</p></section><section class="wrap values">${values.map(value=>'<article class="value-card value-'+value[3]+'"><img src="assets/value-'+value[3]+'.png" alt="" aria-hidden="true"><div class="value-copy"><span>'+value[0]+'</span><h2>'+value[1]+'</h2><p>'+value[2]+'</p></div></article>').join('')}</section>`)}
function contact(){layout(`<section class="contact wrap"><p class="eyebrow">Application / 2025</p><h1>Ваш следующий<br><em>уровень — здесь.</em></h1><p>Индивидуальное сопровождение от $1,000 / месяц. Оставьте заявку, и мы свяжемся для короткого знакомства.</p><form onsubmit="event.preventDefault();this.innerHTML='<h2>Спасибо. Заявка принята.</h2><p>Это демонстрационная форма: внешняя отправка пока не подключена.</p>'"><label>Имя<input required placeholder="Ваше имя" /></label><label>Email<input required type="email" placeholder="you@email.com" /></label><label>Главная цель<select><option>Стать сильнее</option><option>Снизить процент жира</option><option>Вернуть энергию</option></select></label><button class="button">Отправить заявку <b>↗</b></button></form></section>`)}
function notFound(){layout(`<section class="empty wrap"><p class="eyebrow">404</p><h1>Страница<br><em>не найдена.</em></h1><a class="button" href="#/">На главную ↗</a></section>`)}
{
function trainerNotes(){const notes=JSON.parse(localStorage.getItem('elite-private-notes')||'[{"id":1,"client":"Alex Kim","tag":"Technique","text":"Сильная концентрация в тяге. На следующей неделе добавить паузу ниже колена.","date":"19 MAR · 09:12"},{"id":2,"client":"Sofia Martinez","tag":"Recovery","text":"Следим за качеством сна после напряжённой недели.","date":"18 MAR · 18:40"}]'); const render=()=>{layout(`<section class="portal trainer"><aside class="portal-side"><a class="brand" href="#/">ELITE<span>/</span>ONE</a><p class="eyebrow">TRAINER PANEL</p><a href="#/trainer">← Command center</a><a class="active" href="#/trainer/notes">Private notes</a><div class="profile"><div>DR</div><span>Daniel Ross<small>Trainer · demo</small></span></div></aside><section class="portal-main"><p class="eyebrow">⌁ Restricted / trainer only</p><div class="dash-head"><div><h1>Private notes.</h1><p class="muted">Локальные демонстрационные заметки. Клиентская зона не содержит этот маршрут.</p></div><input id="note-search" placeholder="Поиск по заметкам" /></div><div class="note-layout"><form class="note-form" onsubmit="window.addPrivateNote(event)"><label>Клиент<select name="client"><option>Alex Kim</option><option>Sofia Martinez</option><option>Marcus Lee</option></select></label><label>Категория<select name="tag"><option>Technique</option><option>Recovery</option><option>Goal</option><option>Behaviour</option></select></label><label>Наблюдение<textarea required name="text" placeholder="Добавьте приватную заметку…"></textarea></label><button class="button">Сохранить заметку ↗</button></form><div id="note-list">${notes.map(n=>`<article class="note"><div><span>${n.client}</span><small>${n.tag} · ${n.date}</small></div><p>${n.text}</p><button onclick="window.deletePrivateNote(${n.id})">Удалить</button></article>`).join('')}</div></div></section></section>`);document.querySelector('#note-search').addEventListener('input',e=>document.querySelectorAll('.note').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(e.target.value.toLowerCase())))};window.addPrivateNote=e=>{e.preventDefault();let f=new FormData(e.target);notes.unshift({id:Date.now(),client:f.get('client'),tag:f.get('tag'),text:f.get('text'),date:'NOW'});localStorage.setItem('elite-private-notes',JSON.stringify(notes));render()};window.deletePrivateNote=id=>{let p=notes.findIndex(n=>n.id===id);if(p>-1){notes.splice(p,1);localStorage.setItem('elite-private-notes',JSON.stringify(notes));render()}};render()}
function router(){let path=location.hash.slice(1)||'/'; let [_,base,id]=path.split('/'); if(base==='') return home(); if(base==='nutrition') return id!==undefined?article(+id):nutritionPage(); if(base==='workouts') return id!==undefined?exercise(+id):workoutsPage(); if(base==='trainer'&&id==='notes')return trainerNotes(); ({about,programs:programsPage,progress:progressPage,client:clientPage,trainer:trainerPage,contact}[base]||notFound)()}
window.addEventListener('hashchange',router);
}

/* Production portal layer. Public editorial pages above intentionally keep their
   original artwork and motion; authenticated data is loaded only from the API. */
const api = async (path, options = {}) => {
  const response = await fetch(`/api${path}`, {
    credentials: 'same-origin',
    headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) },
    ...options,
  });
  if (response.status === 204) return null;
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || 'Не удалось выполнить запрос.');
  return payload;
};
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' })[char]);
const apiDate = (value, options = { day: 'numeric', month: 'short', year: 'numeric' }) => value ? new Intl.DateTimeFormat('ru-RU', options).format(new Date(value)) : '—';
const portalSide = (role, name) => `<aside class="portal-side"><a class="brand" href="#/">ELITE<span>/</span>ONE</a><p class="eyebrow">${role === 'TRAINER' ? 'TRAINER PANEL' : 'CLIENT AREA'}</p>${role === 'TRAINER' ? '<a href="#/trainer">Command center</a><a href="#/trainer/notes">Private notes</a>' : '<a href="#/client">Overview</a><a href="#/client/profile">Profile</a><a href="#/client/workouts">My program</a><a href="#/client/nutrition">Nutrition plan</a><a href="#/client/progress">Progress</a>'}<button class="portal-logout" data-logout>Выйти</button><div class="profile"><div>${escapeHtml(name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div><span>${escapeHtml(name)}<small>${role === 'TRAINER' ? 'Trainer' : 'Client'}</small></span></div></aside>`;
async function currentUser(){ return (await api('/auth/me')).user; }
async function requirePortal(role){ const user = await currentUser(); if(!user){ location.hash = '#/login'; return null; } if(user.role !== role){ location.hash = user.role === 'TRAINER' ? '#/trainer' : user.role === 'CLIENT' ? '#/client' : '#/'; return null; } return user; }
function bindLogout(){ document.querySelector('[data-logout]')?.addEventListener('click', async ()=>{ await api('/auth/logout',{method:'POST'}); location.hash='#/'; }); }
function authPage(mode = 'login'){
  layout(`<section class="auth-page wrap"><p class="eyebrow">ELITE / ONE ACCOUNT</p><div class="auth-card"><h1>${mode === 'register' ? 'Создайте <em>аккаунт.</em>' : 'С возвращением.'}</h1><p class="muted">${mode === 'register' ? 'Регистрация создаёт клиентский кабинет. Тренеров создаёт администратор системы.' : 'Войдите, чтобы открыть персональный кабинет.'}</p><form id="auth-form">${mode === 'register' ? '<label>Имя<input name="firstName" required maxlength="80" autocomplete="given-name"></label><label>Фамилия<input name="lastName" required maxlength="80" autocomplete="family-name"></label>' : ''}<label>Email<input name="email" required type="email" autocomplete="email"></label><label>Пароль<input name="password" required type="password" minlength="10" autocomplete="${mode === 'register' ? 'new-password' : 'current-password'}"></label><p class="form-error" id="auth-error" aria-live="polite"></p><button class="button" type="submit">${mode === 'register' ? 'Создать аккаунт' : 'Войти'} <b>→</b></button></form><p class="muted">${mode === 'register' ? 'Уже есть аккаунт?' : 'Впервые здесь?'} <a href="#/${mode === 'register' ? 'login' : 'register'}">${mode === 'register' ? 'Войти' : 'Зарегистрироваться'}</a></p></div></section>`);
  document.querySelector('#auth-form').addEventListener('submit', async event => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.currentTarget)); const error = document.querySelector('#auth-error'); error.textContent=''; try { const result = await api(`/auth/${mode === 'register' ? 'register' : 'login'}`, { method:'POST', body:JSON.stringify(form) }); location.hash = result.user.role === 'TRAINER' ? '#/trainer' : '#/client'; } catch(err) { error.textContent = err.message; } });
}
function clientNav(target){ return `<div class="portal-links"><a href="#/client" ${target==='home'?'class="active"':''}>Overview</a><a href="#/client/profile" ${target==='profile'?'class="active"':''}>Profile</a><a href="#/client/workouts" ${target==='workouts'?'class="active"':''}>My program</a><a href="#/client/nutrition" ${target==='nutrition'?'class="active"':''}>Nutrition plan</a><a href="#/client/progress" ${target==='progress'?'class="active"':''}>Progress</a></div>`; }
